29:     static EvidenceCollectionBaseline captureBaseline(WorkflowFileLedger ledger, WorkstreamPaths paths,
30:                                                        WorkflowDefinition definition, String action) throws IOException {
31:         var current = ledger.loadCurrent(paths);
32:         if (current.status() != WorkflowStatus.WAITING_FOR_HUMAN || current.activeNodeInstanceIds().size() != 1
33:                 ) throw new IOException("collection requires a waiting human gate");
34:         var node = ledger.loadNode(paths, current.activeNodeInstanceIds().getFirst());
35:         var gate = ledger.loadOpenGateForNode(paths, node.nodeInstanceId());
36:         if (gate == null || !HumanGateActionSemantics.allowedActions(definition.node(node.nodeDefinitionId()),
37:                 String.valueOf(gate.result().get("source_outcome"))).contains(action))
38:             throw new IOException("collection is not available at this gate");
39:         var resolution = TaskContractProjectionVerifier.resolve(paths.workspaceRoot(), paths.workstreamId().value());
40:         var qualified = resolution.qualified().orElseThrow(() -> new IOException(
41:                 "collection requires a qualified approved task contract: " + resolution.failure()));
42:         var included = qualified.contract().scope().included().stream().map(entry -> entry.path()).toList();
43:         var source = EvidenceCollectionSource.capture(paths.workspaceRoot(), included);
44:         var baseline = new EvidenceCollectionBaseline(node.nodeInstanceId(), qualified.contractRef(), qualified.sha256(),
45:                 source.head(), source.indexSha256(), source.sha256(), source.paths());
46:         verifySource(paths.workspaceRoot(), baseline);
47:         return baseline;

30:     public static Reference prepare(WorkflowFileLedger ledger, WorkstreamPaths paths) throws IOException {
31:         try (var lock = WorkstreamLock.acquire(paths.workstreamDir(), LockOwner.currentProcess(paths.workstreamId().value(), "prepare evidence"))) {
32:             var baseline = EvidenceCollection.captureBaseline(ledger, paths, ledger.loadDefinition(paths), "submit_evidence");
33:             return save(paths, "preparations", JSON.writeValueAsBytes(new Preparation(baseline, Instant.now())), ".json");
34:         }
35:     }
