37:     public static EvidenceSubmission submit(WorkflowFileLedger ledger, WorkstreamPaths paths, Reference preparation,
38:                                              String requestId, List<Path> files, Declaration execution, String note) throws IOException {
39:         if (blank(note) || requestId == null || !requestId.matches("[A-Za-z0-9._-]{1,80}")
40:                 || files == null || files.isEmpty() || files.size() > 32 || execution == null)
41:             throw new IOException("submission requires request id, note, declaration, and 1-32 explicit files");
42:         var prepared = readPreparation(paths, preparation);
43:         if (execution.startedAt().isBefore(prepared.recordedAt()))
44:             throw new IOException("declared execution precedes preparation; timestamps are operator declarations, not machine proof");
45:         EvidenceCollection.verifySource(paths.workspaceRoot(), prepared.baseline());
